def parse_ini(text):
    """Parse INI text into sections of string keys and values."""
    sections = {}
    section = ""
    last_key = None
    for number, raw in enumerate(text.split("\n"), 1):
        line = raw.strip()
        if not line or line.startswith(("#", ";")):
            continue

        if line.startswith("[") and line.endswith("]"):
            section = line[1:-1].strip()
            if not section:
                raise ValueError(f"empty section name on line {number}")
            sections.setdefault(section, {})
            last_key = None
        elif raw.startswith((" ", "\t")):
            if last_key is None:
                raise ValueError(f"continuation without a key on line {number}")
            sections[section][last_key] += "\n" + line
        else:
            key, separator, value = line.partition("=")
            if not separator or not key.strip():
                raise ValueError(f"invalid assignment on line {number}")
            last_key = key.strip().lower()
            sections.setdefault(section, {})[last_key] = value.strip()
    return sections
